package com.andye.warmod.radar.client;import com.andye.warmod.antiair.AntiAirRoute;import com.andye.warmod.icbm.*;import com.andye.warmod.radar.*;import com.andye.warmod.warhead.*;import java.util.*;import net.minecraft.world.phys.Vec3;public final class ClientRadarTrack{private RadarTrackSnapshot snapshot;private List<Vec3> carrierRoute=List.of(),terminalRoute=List.of();private double carrierDuration,terminalDuration;public ClientRadarTrack(RadarTrackSnapshot s){snapshot=s;rebuildRoutes();}public void update(RadarTrackSnapshot s){snapshot=s;rebuildRoutes();}public RadarTrackSnapshot snapshot(){return snapshot;}public UUID id(){return snapshot.trackId();}public List<Vec3> carrierRoute(){return carrierRoute;}public List<Vec3> terminalRoute(){return terminalRoute;}public double carrierDuration(){return carrierDuration;}public double terminalDuration(){return terminalDuration;}public Vec3 position(double time){if(snapshot.phase()==RadarTrackPhase.IMPACT)return target();if(snapshot.interceptorPlan().isPresent())return interceptorPosition(snapshot.interceptorPlan().get(),time);if(snapshot.terminalPlan().isPresent()){var p=snapshot.terminalPlan().get();return WarheadTrajectory.position(p.startPosition(),p.targetPosition(),Math.max(0,time-p.launchGameTime()),p.flightTicks());}if(snapshot.carrierPlan().isPresent())return IcbmTrajectory.position(asPlan(snapshot.carrierPlan().get()),Math.max(0,time-snapshot.carrierPlan().get().launchGameTime()));return Vec3.ZERO;}public Vec3 velocity(double time){if(snapshot.interceptorPlan().isPresent())return position(time+.25).subtract(position(time-.25)).scale(2);if(snapshot.terminalPlan().isPresent()){var p=snapshot.terminalPlan().get();return WarheadTrajectory.velocity(p.startPosition(),p.targetPosition(),Math.max(0,time-p.launchGameTime()),p.flightTicks());}if(snapshot.carrierPlan().isPresent())return IcbmTrajectory.velocity(asPlan(snapshot.carrierPlan().get()),Math.max(0,time-snapshot.carrierPlan().get().launchGameTime()));return Vec3.ZERO;}public double carrierElapsed(double time){return snapshot.interceptorPlan().map(p->Math.max(0,time-p.launchGameTime())).orElseGet(()->snapshot.carrierPlan().map(p->Math.max(0,time-p.launchGameTime())).orElse(0.0));}public double terminalElapsed(double time){return snapshot.terminalPlan().map(p->Math.max(0,time-p.launchGameTime())).orElse(0.0);}public Vec3 target(){return snapshot.interceptorPlan().map(p->p.route().map(RadarInterceptorRouteSnapshot::resolvedInterceptPosition).orElse(p.burnoutPosition())).orElseGet(()->snapshot.terminalPlan().map(RadarTerminalPlanSnapshot::targetPosition).orElseGet(()->snapshot.carrierPlan().map(RadarCarrierPlanSnapshot::intendedTarget).orElse(Vec3.ZERO)));}public Vec3 launch(){return snapshot.interceptorPlan().map(RadarInterceptorPlanSnapshot::launchPosition).orElseGet(()->snapshot.carrierPlan().map(RadarCarrierPlanSnapshot::launchPosition).orElseGet(()->snapshot.terminalPlan().map(RadarTerminalPlanSnapshot::startPosition).orElse(Vec3.ZERO)));}
private Vec3 interceptorPosition(RadarInterceptorPlanSnapshot p,double time){long boostEnd=p.launchGameTime()+p.ignitionTicks()+p.boostTicks();if(p.fallback().isPresent()&&time>=p.fallback().get().transitionGameTime()){var f=p.fallback().get();return com.andye.warmod.antiair.AntiAirFallbackTrajectory.positionAt(f.transitionPosition(),f.transitionVelocity(),time-f.transitionGameTime());}if(time<=boostEnd||p.route().isEmpty())return com.andye.warmod.antiair.AntiAirTrajectory.boostPosition(p.launchPosition(),p.burnoutPosition(),p.noTargetHorizontalOffset(),p.ignitionTicks(),p.boostTicks(),time-p.launchGameTime());var r=p.route().get();AntiAirRoute route=new AntiAirRoute(p.burnoutPosition(),r.controlPoint1(),r.controlPoint2(),r.resolvedInterceptPosition(),r.interceptTicks());return route.position(time-r.routeLockGameTime());}private void rebuildRoutes(){terminalRoute=snapshot.terminalPlan().map(this::sampleTerminal).orElseGet(List::of);if(snapshot.interceptorPlan().isPresent())carrierRoute=sampleInterceptor(snapshot.interceptorPlan().get());else carrierRoute=snapshot.carrierPlan().map(this::sampleCarrier).orElseGet(List::of);}private List<Vec3> sampleInterceptor(RadarInterceptorPlanSnapshot p){carrierDuration=p.ignitionTicks()+p.boostTicks()+p.route().map(RadarInterceptorRouteSnapshot::interceptTicks).orElse(0);ArrayList<Vec3> out=new ArrayList<>();for(int i=0;i<=96;i++)out.add(interceptorPosition(p,p.launchGameTime()+carrierDuration*i/96.0));return List.copyOf(out);}private List<Vec3> sampleCarrier(RadarCarrierPlanSnapshot p){IcbmFlightPlan plan=asPlan(p);carrierDuration=plan.separationTick();ArrayList<Vec3> out=new ArrayList<>();for(int i=0;i<=96;i++)out.add(IcbmTrajectory.position(plan,carrierDuration*i/96));return List.copyOf(out);}private List<Vec3> sampleTerminal(RadarTerminalPlanSnapshot p){terminalDuration=p.flightTicks();ArrayList<Vec3> out=new ArrayList<>();for(int i=0;i<=48;i++)out.add(WarheadTrajectory.position(p.startPosition(),p.targetPosition(),terminalDuration*i/48,p.flightTicks()));return List.copyOf(out);}private IcbmFlightPlan asPlan(RadarCarrierPlanSnapshot p){return new IcbmFlightPlan(snapshot.trackId(),snapshot.ownerPlayerId(),p.launchPosition(),p.burnoutPosition(),p.separationPosition(),p.intendedTarget(),p.launchGameTime(),p.ignitionTicks(),p.boostTicks(),p.coastTicks(),p.visualSeed(),snapshot.strategicPayloadType().orElseThrow());}}